// Building parts in one oblique view (depth runs up and to the right): boxes with arched windows, stairs whose treads
// and risers show, and an observatory. Fills are colourway roles; side faces are the fill darkened toward ink and
// stippled, like the triptych's shaded walls.
import { crescent, ellipse, circle, line, shape, stipple, tint } from "./motifs"
import { el, n, type Pen, type Rs } from "./svg"

export const DEPTH = [24, -15] as const
type Pt = readonly [number, number]

export const shade = (f: string, k = 84) =>
  `color-mix(in oklab, var(--${f}) ${k}%, var(--ink))`
export const tintOf = (f: string, k = 45) =>
  `color-mix(in oklab, var(--${f}) ${k}%, var(--paper))`
export const quad = (pts: readonly Pt[]) =>
  `M ${pts.map(([x, y]) => `${n(x)} ${n(y)}`).join(" L ")} Z`
export const archPath = (x: number, base: number, w: number, h: number) => {
  const r = w / 2
  const spring = Math.min(base, base - h + r)
  return `M ${n(x)} ${n(base)} V ${n(spring)} A ${n(r)} ${n(r)} 0 0 1 ${n(x + w)} ${n(spring)} V ${n(base)} Z`
}

/** A box: front face, top and right side, with a row of arched ink cavities on the front. */
export function box(
  p: Pen,
  {
    x,
    y,
    w,
    h,
    fill,
    depth = 1,
    windows = 0,
    top,
  }: {
    x: number
    y: number
    w: number
    h: number
    fill: string
    depth?: number
    windows?: number
    top?: string
  },
) {
  const [dx, dy] = [DEPTH[0] * depth, DEPTH[1] * depth]
  const side = quad([
    [x + w, y],
    [x + w + dx, y + dy],
    [x + w + dx, y + h + dy],
    [x + w, y + h],
  ])
  let out =
    shape(p, side, shade(fill)) +
    tint(side, stipple(p)) +
    shape(
      p,
      quad([
        [x, y],
        [x + dx, y + dy],
        [x + w + dx, y + dy],
        [x + w, y],
      ]),
      top ?? tintOf(fill),
    ) +
    shape(
      p,
      quad([
        [x, y],
        [x + w, y],
        [x + w, y + h],
        [x, y + h],
      ]),
      fill,
    )
  if (windows) {
    const ww = Math.min(26, w / (windows * 1.9))
    const gap = (w - windows * ww) / (windows + 1)
    const wh = Math.min(h * 0.5, ww * 2.1)
    for (let i = 0; i < windows; i++)
      out += shape(
        p,
        archPath(x + gap + i * (ww + gap), y + h * 0.22 + wh, ww, wh),
        "ink",
      )
  }
  return out
}

/** A stair rising to the left from (x0, y0) to (x1, y1): paper treads, shaded risers, a coloured stringer. */
export function steps(
  p: Pen,
  {
    x0,
    y0,
    x1,
    y1,
    count,
    fill,
    depth = 1.1,
    under = 26,
  }: {
    x0: number
    y0: number
    x1: number
    y1: number
    count: number
    fill: string
    depth?: number
    under?: number
  },
) {
  const run = (x0 - x1) / count
  const rise = (y0 - y1) / count
  const [dx, dy] = [DEPTH[0] * depth, DEPTH[1] * depth]
  let parts = ""
  let profile = `M ${n(x0)} ${n(y0 + under)} L ${n(x0)} ${n(y0)}`
  for (let k = 0, x = x0, y = y0; k < count; k++, x -= run, y -= rise) {
    parts += shape(
      p,
      quad([
        [x, y],
        [x, y - rise],
        [x + dx, y - rise + dy],
        [x + dx, y + dy],
      ]),
      shade(fill, 78),
    )
    parts += shape(
      p,
      quad([
        [x, y - rise],
        [x - run, y - rise],
        [x - run + dx, y - rise + dy],
        [x + dx, y - rise + dy],
      ]),
      "paper",
    )
    profile += ` V ${n(y - rise)} H ${n(x - run)}`
  }
  profile += ` V ${n(y1 + under)} Z`
  const shadow = `M ${n(x1)} ${n(y1 + under * 0.4)} L ${n(x0)} ${n(y0 + under * 0.4)} V ${n(y0 + under)} L ${n(x1)} ${n(y1 + under)} Z`
  return parts + shape(p, profile, fill) + tint(shadow, stipple(p))
}

/** An observatory: a drum with windows, a ribbed dome with its slit open, and a telescope looking out. */
export function observatory(
  p: Pen,
  r: Rs,
  {
    cx,
    base,
    rad,
    fill,
  }: { cx: number; base: number; rad: number; fill: string },
) {
  const drum = rad * 0.62
  let out = box(p, {
    x: cx - rad,
    y: base - drum,
    w: rad * 2,
    h: drum,
    fill,
    depth: 0.7,
    windows: 4,
  })
  const dcx = cx + DEPTH[0] * 0.35
  const dbase = base - drum + DEPTH[1] * 0.35
  const rd = rad * 0.92
  const dome = `M ${n(dcx - rd)} ${n(dbase)} A ${n(rd)} ${n(rd)} 0 0 1 ${n(dcx + rd)} ${n(dbase)} Z`
  const clip = p.uid("dome")
  const tilt = r.between(-0.9, -0.5)
  const [tx, ty] = [dcx - rd * 0.1, dbase - rd * 0.62]
  const [c, s] = [Math.cos(tilt), Math.sin(tilt)]
  const tube = (len: number, w0: number, w1: number) =>
    quad([
      [tx - s * w0, ty + c * w0],
      [tx + c * len - s * w1, ty + s * len + c * w1],
      [tx + c * len + s * w1, ty + s * len - c * w1],
      [tx + s * w0, ty - c * w0],
    ])
  out += el("clipPath", { id: clip }, el("path", { d: dome }, null))
  out += shape(p, dome, "paper")
  out += tint(crescent(dcx, dbase, rd, -rd * 0.55, -rd * 0.25), stipple(p), {
    "clip-path": `url(#${clip})`,
  })
  let ribs = ""
  for (const k of [-0.62, -0.3, 0.3, 0.62])
    ribs += `M ${n(dcx + k * rd)} ${n(dbase)} Q ${n(dcx + k * rd * 0.9)} ${n(dbase - rd * 0.85)} ${n(dcx)} ${n(dbase - rd)} `
  out += line(p, ribs, { "clip-path": `url(#${clip})` })
  out += shape(
    p,
    `M ${n(dcx - rd * 0.12)} ${n(dbase - rd * 0.99)} H ${n(dcx + rd * 0.12)} V ${n(dbase - rd * 0.2)} H ${n(dcx - rd * 0.12)} Z`,
    "ink",
  )
  out += shape(p, tube(rd * 0.95, 11, 15), "paper")
  const [mx, my] = [tx + c * rd * 0.95, ty + s * rd * 0.95]
  out += shape(p, ellipse(mx, my, 6, 14), "ink", {
    transform: `rotate(${n((tilt * 180) / Math.PI)} ${n(mx)} ${n(my)})`,
  })
  return (
    out +
    shape(
      p,
      `M ${n(dcx - 3)} ${n(dbase - rd - 26)} H ${n(dcx + 3)} V ${n(dbase - rd + 2)} H ${n(dcx - 3)} Z`,
      "paper",
    ) +
    shape(p, circle(dcx, dbase - rd - 30, 6), "paper")
  )
}

// Cloud banks and the arcade band. A bank is puffs on a flat base, outlined as one shape (every part stroked at twice
// the line, then filled on top without one) with open arcs inside where one puff overlaps another; a floating bank
// (a stratum in the sky) is cut flat and outlined at its base.
import { circle, line, paint, stipple, tint } from "./motifs"
import { el, n, type Pen, type Rs } from "./svg"

export interface Bank {
  x0: number
  x1: number
  base: number
  top: number
  rmin: number
  rmax: number
  fill: string
  contours?: number
  floating?: boolean
}

export function cloudBank(p: Pen, r: Rs, b: Bank) {
  const {
    x0,
    x1,
    base,
    top,
    rmin,
    rmax,
    fill,
    contours = 0.65,
    floating = false,
  } = b
  const puffs: { cx: number; cy: number; r: number }[] = []
  let x = x0 - rmax * 0.3
  while (x < x1 + rmax * 0.3) {
    const rad = r.between(rmin, rmax)
    puffs.push({
      cx: x,
      cy: r.between(top + rad, top + rad + (rmax - rmin) * 0.8),
      r: rad,
    })
    x += rad * r.between(1.05, 1.45)
  }
  if (floating)
    for (const q of puffs) {
      q.cx = Math.min(Math.max(q.cx, x0 + q.r * 0.6), x1 - q.r * 0.6)
      q.cy = Math.min(q.cy, base - q.r * 0.3)
    }
  const shelf = Math.min(
    puffs.reduce((s, q) => s + q.cy, 0) / puffs.length,
    base - 4,
  )
  const [left, right] = floating ? [x0, x1] : [x0 - rmax, x1 + rmax]
  const parts =
    puffs.map((q) => circle(q.cx, q.cy, q.r)).join(" ") +
    ` M ${n(left)} ${n(shelf)} H ${n(right)} V ${n(floating ? base : base + 40)} H ${n(left)} Z`
  let arcs = ""
  puffs.forEach((q, i) => {
    if (i === 0 || !r.chance(contours)) return
    const a0 = (r.between(192, 205) * Math.PI) / 180
    const a1 = (r.between(238, 262) * Math.PI) / 180
    const pt = (a: number) =>
      `${n(q.cx + Math.cos(a) * q.r)} ${n(q.cy + Math.sin(a) * q.r)}`
    arcs += `M ${pt(a0)} A ${n(q.r)} ${n(q.r)} 0 0 1 ${pt(a1)} `
  })
  const clip = p.uid("cloud")
  let defs = el("clipPath", { id: clip }, el("path", { d: parts }, null))
  let cutInk = {}
  let cutFill = {}
  if (floating) {
    const [ci, cf] = [p.uid("ci"), p.uid("cf")]
    const box = (y: number) =>
      el(
        "rect",
        {
          x: left - rmax * 2,
          y: top - rmax,
          width: right - left + rmax * 4,
          height: y - top + rmax,
        },
        null,
      )
    defs +=
      el("clipPath", { id: ci }, box(base + p.L * 1.2)) +
      el("clipPath", { id: cf }, box(base))
    cutInk = { "clip-path": `url(#${ci})` }
    cutFill = { "clip-path": `url(#${cf})` }
  }
  return (
    defs +
    el(
      "path",
      {
        d: parts,
        style: "fill:var(--ink);stroke:var(--ink)",
        "stroke-width": p.L * 2,
        "vector-effect": "non-scaling-stroke",
        ...cutInk,
      },
      null,
    ) +
    tint(parts, paint(fill), cutFill) +
    (arcs
      ? el("g", cutFill, line(p, arcs, { "clip-path": `url(#${clip})` }))
      : "")
  )
}

/**
 * The arcade band between sections: a wall in `fill` whose arched openings show the section below, each opening
 * revealing the wall's thickness, stippled, along its right side.
 */
export function arcadeBand(
  p: Pen,
  {
    width = 1200,
    height = 104,
    bay = 124,
    pier = 34,
    rise = 62,
    depth = 10,
    fill = "cloud",
  } = {},
) {
  const r = (bay - pier) / 2
  const foot = height - 2
  const spring = foot - rise + r
  const arch = (a: number, c: number) =>
    `M ${n(a)} ${n(foot)} V ${n(spring)} A ${n(r)} ${n(r)} 0 0 1 ${n(c)} ${n(spring)} V ${n(foot)}`
  let holes = ""
  let inner = ""
  let edges = ""
  for (let x = -bay; x < width + bay; x += bay) {
    const [a, c] = [x + pier / 2, x + bay - pier / 2]
    holes += `${arch(a, c)} Z `
    inner += `${arch(a - depth, c - depth)} Z `
    edges += `${arch(a, c)} M ${n(c)} ${n(foot)} H ${n(c + pier)} `
  }
  const big = `M ${-bay} 0 H ${width + bay} V ${n(foot)} H ${-bay} Z`
  const clip = p.uid("arches")
  const reveal = { "fill-rule": "evenodd", "clip-path": `url(#${clip})` }
  return (
    el("clipPath", { id: clip }, el("path", { d: holes }, null)) +
    tint(`${big} ${holes}`, fill, { "fill-rule": "evenodd" }) +
    tint(`${big} ${inner}`, fill, reveal) +
    tint(`${big} ${inner}`, stipple(p), reveal) +
    line(p, inner, { "clip-path": `url(#${clip})` }) +
    line(p, edges, { "stroke-linecap": "square" })
  )
}

// The smaller formats: a window for arch-topped card images, a medallion, the band between sections, the arcade wall
// at a section's head and the doorway of an empty state.
import { box, DEPTH, observatory } from "./buildings"
import { pinwheelArch, plant } from "./plants"
import { arcadeBand, cloudBank } from "./clouds"
import { circle, pinwheel, scatter, shape } from "./motifs"
import { platform } from "./parts"
import { el, rs } from "./svg"
import type { Scene } from "./scene"

/** A window: a platform and dome above clouds under a pinwheel sun, for an arch-topped card image. */
export const windowScene: Scene = {
  w: 300,
  h: 320,
  fit: "xMidYMax slice",
  body: (p, seed) => {
    const [W, ground] = [300, 360]
    const r = (k: string) => rs(seed, k)
    const sun = r("sun")
    return (
      pinwheel(
        p,
        sun.between(200, 240),
        sun.between(70, 96),
        sun.between(30, 38),
        "sun",
        { turn: sun.next() * 6 },
      ) +
      scatter(p, r("sky"), {
        x0: 20,
        y0: 20,
        x1: 180,
        y1: 120,
        sparkles: 2,
        rings: 2,
        dots: 3,
        size: [6, 10],
      }) +
      cloudBank(p, r("back"), {
        x0: 0,
        x1: W,
        base: ground,
        top: 170,
        rmin: 26,
        rmax: 44,
        fill: "paper",
      }) +
      platform(p, r("platform"), {
        cx: r("px").between(120, 170),
        cy: 180,
        rx: 78,
        ground,
        dome: true,
      }) +
      cloudBank(p, r("front"), {
        x0: 0,
        x1: W,
        base: ground,
        top: 236,
        rmin: 22,
        rmax: 38,
        fill: "cloud",
      })
    )
  },
}

/** A medallion: a pinwheel, or a pinwheel seen through an arch on clouds, in a round frame (avatars, featured figures). */
export const medallion: Scene = {
  w: 120,
  h: 120,
  fit: "xMidYMid meet",
  body: (p, seed) => {
    const r = rs(seed, "medallion")
    const clip = p.uid("medal")
    const ring = circle(60, 60, 54)
    const inner = r.chance(0.5)
      ? pinwheel(p, 60, 60, 70, r.pick(["sun", "bloom", "structure"]), {
          turn: r.next() * 6,
          ring: false,
        })
      : shape(p, "M 0 0 H 120 V 120 H 0 Z", "canvas") +
        pinwheelArch(p, {
          x: r.between(30, 36),
          base: 104,
          w: 52,
          h: 74,
          frame: r.pick(["structure", "bloom", "platform"]),
          colour: "sun",
        }) +
        cloudBank(p, rs(seed, "medal-cloud"), {
          x0: 0,
          x1: 120,
          base: 140,
          top: 92,
          rmin: 10,
          rmax: 16,
          fill: "cloud",
        })
    return (
      el("clipPath", { id: clip }, el("path", { d: ring }, null)) +
      el("g", { "clip-path": `url(#${clip})` }, inner) +
      shape(p, ring, "none")
    )
  },
}

/** The band between sections: a cloud bank with a building rising behind it and a plant in front. */
export const band: Scene = {
  w: 3200,
  h: 210,
  fit: "xMidYMax slice",
  body: (p, seed) => {
    const [w, h] = [3200, 210]
    const r = (k: string) => rs(seed, k)
    const s = h / 200
    const ax = w / 2 + r("x").between(80, 360)
    const kind = r("kind").pick(["observatory", "arch", "tower"])
    let art = cloudBank(p, r("back"), {
      x0: w / 2 - 200,
      x1: w,
      base: h,
      top: h * 0.36,
      rmin: h * 0.1,
      rmax: h * 0.18,
      fill: "paper",
    })
    if (kind === "observatory") {
      art += box(p, {
        x: ax,
        y: h * 0.5,
        w: 150 * s,
        h,
        fill: "tone-1",
        windows: 3,
      })
      art += observatory(p, r("obs"), {
        cx: ax + 75 * s,
        base: h * 0.5 + DEPTH[1] * 0.5,
        rad: 62 * s,
        fill: "plane-2",
      })
    } else if (kind === "arch") {
      art += box(p, {
        x: ax + 150 * s,
        y: h * 0.34,
        w: 80 * s,
        h,
        fill: "tone-2",
        windows: 1,
      })
      art += box(p, { x: ax, y: h * 0.1, w: 140 * s, h, fill: "tone-3" })
      art += pinwheelArch(p, {
        x: ax + 24 * s,
        base: h * 0.7,
        w: 92 * s,
        h: h * 0.52,
        frame: "leaf",
        colour: "bloom",
      })
    } else {
      art += box(p, {
        x: ax + 92 * s,
        y: h * 0.3,
        w: 80 * s,
        h,
        fill: "tone-2",
        windows: 1,
      })
      art += box(p, {
        x: ax,
        y: h * 0.08,
        w: 96 * s,
        h,
        fill: "tone-4",
        windows: 2,
      })
    }
    art += cloudBank(p, r("clouds"), {
      x0: 0,
      x1: w,
      base: h,
      top: h * 0.56,
      rmin: h * 0.11,
      rmax: h * 0.2,
      fill: "cloud",
    })
    art += plant(p, r("plant"), {
      x: w / 2 - r("plant-x").between(260, 520),
      ground: h + 10,
      height: h * 0.95,
      blooms: 2,
    })
    return (
      art +
      scatter(p, r("sky"), {
        x0: w / 2 - 240,
        y0: h * 0.08,
        x1: w / 2 + 60,
        y1: h * 0.45,
        sparkles: 3,
        rings: 2,
        dots: 4,
        size: [6, 11],
      })
    )
  },
}

/** The arcade wall at the head of a section: arches open onto the section below. */
export const arcadeWall: Scene = {
  w: 3200,
  h: 104,
  fit: "xMidYMin slice",
  body: (p) => arcadeBand(p, { width: 3200 }),
}

/** The empty state: an archway with a solid ink doorway, a sparkle above it, on a small cloud. */
export const doorway: Scene = {
  w: 160,
  h: 150,
  fit: "xMidYMax meet",
  body: (p, seed) => {
    const r = rs(seed, "doorway")
    return (
      shape(p, "M 40 132 V 62 A 40 40 0 0 1 120 62 V 132 Z", "structure") +
      shape(p, "M 64 132 V 88 A 16 16 0 0 1 96 88 V 132 Z", "ink") +
      scatter(p, r, {
        x0: 20,
        y0: 6,
        x1: 140,
        y1: 30,
        sparkles: 2,
        rings: 1,
        dots: 2,
        size: [6, 10],
      }) +
      cloudBank(p, rs(seed, "doorway-cloud"), {
        x0: 6,
        x1: 154,
        base: 146,
        top: 112,
        rmin: 9,
        rmax: 15,
        fill: "cloud",
        floating: true,
      })
    )
  },
}

// Follies: seeded surreal architecture in the triptych's manner, drawn as SVG strings from a seed. Every fill is a
// colourway role, so a drawing reprints in every colourway; the same seed draws the same SVG on the server, in the
// browser and in every build. Framework-free: no React, no DOM, no Math.random().
import { MOTIFS, type Motif } from "./marks"
import type { Scene } from "./scene"
import { defs, pitchOf, seedNumber, TEMPLATES, type Template } from "./scenes"
import { el, pen } from "./svg"

export { TEMPLATES, type Template } from "./scenes"
export { MOTIFS, type Motif } from "./marks"
export { seedOf, prng, fork, stream } from "./seed"

interface Drawn {
  /** Any string or number; the same seed always draws the same folly. */
  seed?: string | number
  /** The line in CSS pixels (non-scaling, so it holds at any size). */
  line?: number
  /** An accessible name; without one the drawing is decorative and hidden from assistive technology. */
  label?: string
}

export interface FollyOptions extends Drawn {
  /** Which drawing: the city, a window, a medallion, a band, the arcade wall or the doorway. */
  template?: Template
}

export interface MotifOptions extends Drawn {
  /** Which motif: a pinwheel, a sparkle, a cloud or an archway. */
  kind?: Motif
}

/** One scene as an SVG string, sized by its container (width and height 100%). */
function draw(
  scene: Scene,
  name: string,
  data: Record<string, string>,
  pitch: number,
  { seed = "serigraph", line = 1.5, label }: Drawn,
) {
  const p = pen(String(seed), name, line)
  const body = defs(p, pitch) + scene.body(p, seedNumber(seed))
  const a11y = label
    ? { role: "img", "aria-label": label.replace(/[<>&"]/g, "") }
    : { "aria-hidden": "true" }
  return el(
    "svg",
    {
      xmlns: "http://www.w3.org/2000/svg",
      viewBox: `0 0 ${scene.w} ${scene.h}`,
      preserveAspectRatio: scene.fit,
      width: "100%",
      height: "100%",
      focusable: "false",
      ...data,
      ...a11y,
    },
    body,
  )
}

/** A folly as an SVG string, sized by its container (width and height 100%). */
export const folly = ({ template = "city", ...options }: FollyOptions = {}) =>
  draw(
    TEMPLATES[template],
    template,
    { "data-folly": template },
    pitchOf(template),
    options,
  )

/** A motif on its own as an SVG string, sized by its container; it keeps its proportions inside the box. */
export const motif = ({ kind = "sparkle", ...options }: MotifOptions = {}) =>
  draw(MOTIFS[kind], `motif-${kind}`, { "data-motif": kind }, 2.6, options)

// The motifs on their own, for places a whole folly is too much: a pinwheel (medallions, a spinner), a sparkle ("new",
// success, empty space), a cloud (under a heading, behind a dialog's art) and an archway (image frames, empty
// states). Each is a Scene like the templates, so motif() frames it the same way. A motif's colour is its role, or
// --motif where the page sets one.
import { archPath } from "./buildings"
import {
  circle,
  line,
  pinpoint,
  pinwheel,
  ring,
  shape,
  sparkle,
  tint,
} from "./motifs"
import { el, n, rs } from "./svg"
import type { Scene } from "./scene"

const colour = (role: string) => `var(--motif, var(--${role}))`

/** Twelve curved wedges of paper and one colour in a fine ring; the seed sets the twist and the turn. */
const pinwheelMark: Scene = {
  w: 100,
  h: 100,
  fit: "xMidYMid meet",
  body: (p, seed) => {
    const r = rs(seed, "pinwheel")
    return pinwheel(p, 50, 50, 47, colour("sun"), {
      twist: r.between(0.45, 0.8),
      turn: r.next() * 6,
    })
  },
}

/** A four-point sparkle with a small one, a ring and a pinpoint placed by the seed. */
const sparkleMark: Scene = {
  w: 100,
  h: 100,
  fit: "xMidYMid meet",
  body: (p, seed) => {
    const r = rs(seed, "sparkle")
    const [x, y] = [r.between(70, 82), r.between(16, 26)]
    return (
      sparkle(p, 42, 58, 36) +
      sparkle(p, x, y, r.between(9, 13)) +
      ring(p, r.between(80, 88), r.between(64, 78), 3.4) +
      pinpoint(r.between(12, 22), r.between(14, 26), 1.8)
    )
  },
}

/**
 * A cumulus: puffs rising to a crown and curving down to a flat base, outlined as one shape (stroked at twice the
 * line, then filled on top), with open arcs where one puff overlaps the next.
 */
const cloudMark: Scene = {
  w: 240,
  h: 96,
  fit: "xMidYMax meet",
  body: (p, seed) => {
    const r = rs(seed, "cloud")
    const base = 92
    const count = r.int(4, 6)
    const puffs = Array.from({ length: count }, (_, i) => {
      const t = i / (count - 1)
      const rad = (22 + 26 * Math.sin(Math.PI * t)) * r.between(0.88, 1.08)
      return { cx: 0, cy: base - rad, r: rad, t }
    })
    const first = puffs[0]!
    const last = puffs[count - 1]!
    // Spread the puffs so the outer ones touch the box's sides; the inner ones shift a little.
    const span = 232 - first.r - last.r
    for (const q of puffs) {
      const shift = q === first || q === last ? 0 : r.between(-0.04, 0.04)
      q.cx = 4 + first.r + span * (q.t + shift)
    }
    const shelf = base - Math.min(first.r, last.r)
    const d =
      puffs.map((q) => circle(q.cx, q.cy, q.r)).join(" ") +
      ` M ${n(first.cx)} ${n(shelf)} H ${n(last.cx)} V ${n(base)} H ${n(first.cx)} Z`
    let arcs = ""
    for (const q of puffs.slice(1, -1)) {
      if (!r.chance(0.7)) continue
      const a0 = (r.between(195, 205) * Math.PI) / 180
      const a1 = (r.between(238, 255) * Math.PI) / 180
      const pt = (a: number) =>
        `${n(q.cx + Math.cos(a) * q.r)} ${n(q.cy + Math.sin(a) * q.r)}`
      arcs += `M ${pt(a0)} A ${n(q.r)} ${n(q.r)} 0 0 1 ${pt(a1)} `
    }
    const clip = p.uid("cloud")
    return (
      el("clipPath", { id: clip }, el("path", { d }, null)) +
      el(
        "path",
        {
          d,
          style: "fill:var(--ink);stroke:var(--ink)",
          "stroke-width": p.L * 2,
          "vector-effect": "non-scaling-stroke",
        },
        null,
      ) +
      tint(d, colour("cloud")) +
      (arcs ? line(p, arcs, { "clip-path": `url(#${clip})` }) : "")
    )
  },
}

/** A round-topped opening in a thick frame with a solid ink doorway and a sill. */
const archwayMark: Scene = {
  w: 100,
  h: 124,
  fit: "xMidYMax meet",
  body: (p, seed) => {
    const r = rs(seed, "archway")
    const [w, t] = [r.between(72, 84), r.between(12, 17)]
    const x = (100 - w) / 2
    const base = 116
    const outer = archPath(x, base, w, 108)
    const inner = archPath(x + t, base, w - 2 * t, 108 - t)
    return (
      shape(p, `${outer} ${inner}`, colour("structure"), {
        "fill-rule": "evenodd",
      }) +
      shape(p, inner, "ink") +
      line(p, `M 4 ${base} H 96`)
    )
  },
}

export const MOTIFS = {
  pinwheel: pinwheelMark,
  sparkle: sparkleMark,
  cloud: cloudMark,
  archway: archwayMark,
} as const
export type Motif = keyof typeof MOTIFS

// The style's motifs as SVG fragments: inked shapes, stipple, louvers, pinwheels, sparkles and cloud banks. Fills are
// colourway roles (--structure, --cloud …) or paints; lines are non-scaling, so one line weight serves every size.
import { el, n, type Pen, type Rs } from "./svg"

const TAU = Math.PI * 2

/** A role name ('coral', 'cloud'), any CSS paint ('url(#…)', 'color-mix(…)'), or 'none'. */
export const paint = (f: string) =>
  f === "none" ? "none" : f.includes("(") ? f : `var(--${f})`

type Extra = Record<string, string | number | undefined>

/** A filled shape outlined in ink. */
export const shape = (p: Pen, d: string, fill: string, more: Extra = {}) =>
  el(
    "path",
    {
      d,
      style: `fill:${paint(fill)};stroke:var(--ink)`,
      "stroke-width": p.L,
      "stroke-linejoin": "round",
      "vector-effect": "non-scaling-stroke",
      ...more,
    },
    null,
  )
/** An open ink line. */
export const line = (p: Pen, d: string, more: Extra = {}) =>
  el(
    "path",
    {
      d,
      style: "fill:none;stroke:var(--ink)",
      "stroke-width": p.L,
      "stroke-linecap": "round",
      "vector-effect": "non-scaling-stroke",
      ...more,
    },
    null,
  )
/** A filled shape with no outline (stipple and louver overlays). */
export const tint = (d: string, fill: string, more: Extra = {}) =>
  el("path", { d, style: `fill:${paint(fill)}`, ...more }, null)

export const circle = (cx: number, cy: number, r: number) =>
  `M ${n(cx - r)} ${n(cy)} A ${n(r)} ${n(r)} 0 1 1 ${n(cx + r)} ${n(cy)} A ${n(r)} ${n(r)} 0 1 1 ${n(cx - r)} ${n(cy)} Z`
export const ellipse = (cx: number, cy: number, rx: number, ry: number) =>
  `M ${n(cx - rx)} ${n(cy)} A ${n(rx)} ${n(ry)} 0 1 1 ${n(cx + rx)} ${n(cy)} A ${n(rx)} ${n(ry)} 0 1 1 ${n(cx - rx)} ${n(cy)} Z`

/** The drawing's patterns: a staggered stipple `pitch` units apart, and horizontal louvers in the stair colour. */
export function defs(p: Pen, pitch = 3, period = 10) {
  const dotR = (0.55 * pitch) / 3
  const stipple = el(
    "pattern",
    {
      id: `${p.id}-stipple`,
      width: pitch,
      height: pitch,
      patternUnits: "userSpaceOnUse",
    },
    el(
      "circle",
      { cx: pitch / 4, cy: pitch / 4, r: dotR, style: "fill:var(--ink)" },
      null,
    ) +
      el(
        "circle",
        {
          cx: (3 * pitch) / 4,
          cy: (3 * pitch) / 4,
          r: dotR,
          style: "fill:var(--ink)",
        },
        null,
      ),
  )
  const louvers = el(
    "pattern",
    {
      id: `${p.id}-louvers`,
      width: 8,
      height: period,
      patternUnits: "userSpaceOnUse",
    },
    el("rect", { width: 8, height: period, style: "fill:var(--stair)" }, null) +
      el(
        "rect",
        {
          y: period * 0.32,
          width: 8,
          height: period * 0.68,
          style: "fill:var(--ink)",
        },
        null,
      ),
  )
  return el("defs", {}, stipple + louvers)
}
export const stipple = (p: Pen) => `url(#${p.id}-stipple)`
export const louvers = (p: Pen) => `url(#${p.id}-louvers)`

/** The part of circle (cx, cy, r) left uncovered by the same circle moved by (ox, oy): the shadow side. */
export function crescent(
  cx: number,
  cy: number,
  r: number,
  ox: number,
  oy: number,
) {
  const d = Math.hypot(ox, oy)
  const hh = Math.sqrt(r * r - (d * d) / 4)
  const [mx, my] = [cx + ox / 2, cy + oy / 2]
  const [ux, uy] = [-oy / d, ox / d]
  const p1 = [mx + ux * hh, my + uy * hh] as const
  const p2 = [mx - ux * hh, my - uy * hh] as const
  return `M ${n(p1[0])} ${n(p1[1])} A ${n(r)} ${n(r)} 0 1 1 ${n(p2[0])} ${n(p2[1])} A ${n(r)} ${n(r)} 0 0 0 ${n(p1[0])} ${n(p1[1])} Z`
}

/** A round form in a fill, stippled on its lower right. */
export const ball = (p: Pen, cx: number, cy: number, r: number, fill: string) =>
  tint(circle(cx, cy, r), fill) +
  tint(crescent(cx, cy, r, -r * 0.42, -r * 0.34), stipple(p)) +
  shape(p, circle(cx, cy, r), "none")

/** A pinwheel: curved wedges of paper and `colour` in an ink ring. */
export function pinwheel(
  p: Pen,
  cx: number,
  cy: number,
  r: number,
  colour: string,
  { count = 12, twist = 0.6, turn = 0, ring = true } = {},
) {
  let wedges = ""
  const pt = (a: number, rr: number) =>
    `${n(cx + Math.cos(a) * rr)} ${n(cy + Math.sin(a) * rr)}`
  for (let i = 0; i < count; i++) {
    const a0 = turn + (i * TAU) / count
    const a1 = a0 + TAU / count
    const d = `M ${n(cx)} ${n(cy)} Q ${pt(a0 - twist, r * 0.55)} ${pt(a0, r)} A ${n(r)} ${n(r)} 0 0 1 ${pt(a1, r)} Q ${pt(a1 - twist, r * 0.55)} ${n(cx)} ${n(cy)} Z`
    wedges += tint(d, i % 2 ? "paper" : colour)
  }
  return el(
    "g",
    { class: "pinwheel" },
    wedges + (ring ? shape(p, circle(cx, cy, r), "none") : ""),
  )
}

/** Loose marks in the sky take the surface's text colour: ink on bright canvases, paper on Night's, like stars. */
const LOOSE = "var(--text, var(--ink))"

/** A hollow ring, loose in the sky. */
export const ring = (p: Pen, cx: number, cy: number, r: number) =>
  line(p, circle(cx, cy, r), { style: `fill:none;stroke:${LOOSE}` })

/** A pinpoint dot, loose in the sky. */
export const pinpoint = (cx: number, cy: number, r: number) =>
  tint(circle(cx, cy, r), LOOSE)

/** A four-point concave sparkle, paper inside a fine ink line. */
export function sparkle(p: Pen, x: number, y: number, s: number) {
  const k = s * 0.13
  const d =
    `M ${n(x)} ${n(y - s)} Q ${n(x + k)} ${n(y - k)} ${n(x + s)} ${n(y)} Q ${n(x + k)} ${n(y + k)} ${n(x)} ${n(y + s)} ` +
    `Q ${n(x - k)} ${n(y + k)} ${n(x - s)} ${n(y)} Q ${n(x - k)} ${n(y - k)} ${n(x)} ${n(y - s)} Z`
  return shape(p, d, "paper")
}

/** Sparkles, hollow rings and pinpoint dots scattered in a box. */
export function scatter(
  p: Pen,
  r: Rs,
  {
    x0,
    y0,
    x1,
    y1,
    sparkles = 5,
    rings = 4,
    dots = 6,
    size = [8, 15],
  }: {
    x0: number
    y0: number
    x1: number
    y1: number
    sparkles?: number
    rings?: number
    dots?: number
    size?: [number, number]
  },
) {
  let out = ""
  for (let i = 0; i < sparkles; i++)
    out += sparkle(
      p,
      r.between(x0, x1),
      r.between(y0, y1),
      r.between(size[0], size[1]),
    )
  for (let i = 0; i < rings; i++)
    out += ring(p, r.between(x0, x1), r.between(y0, y1), r.between(2.5, 4.5))
  for (let i = 0; i < dots; i++)
    out += pinpoint(r.between(x0, x1), r.between(y0, y1), 1.6)
  return out
}

// Larger parts of a folly: an arcade with a louvered arch, a round platform with a black underside and an optional
// dome, a stair seen from below with a louvered underside, and a flower on a stem.
import {
  ball,
  crescent,
  ellipse,
  louvers,
  line,
  shape,
  stipple,
  tint,
} from "./motifs"
import { el, n, type Pen, type Rs } from "./svg"

/** An arcade: a deck on piers with arched openings, its top and back face showing its depth. */
export function arcade(
  p: Pen,
  r: Rs,
  { x0, top, ground }: { x0: number; top: number; ground: number },
) {
  const count = r.int(3, 5)
  const bay = r.between(118, 146)
  const [pier, deck] = [30, 36]
  const x1 = x0 + count * bay + pier
  const [dx, dy] = [22, -14]
  const face = (ox: number, oy: number) => {
    let d = `M ${n(x0 + ox)} ${n(top + oy)} H ${n(x1 + ox)} V ${n(ground + oy)} H ${n(x0 + ox)} Z`
    for (let i = 0; i < count; i++) {
      const a = x0 + pier + i * bay + ox
      const c = a + bay - pier
      const rad = (c - a) / 2
      const spring = top + deck + rad + oy
      d += ` M ${n(a)} ${n(ground + oy)} V ${n(spring)} A ${n(rad)} ${n(rad)} 0 0 1 ${n(c)} ${n(spring)} V ${n(ground + oy)} Z`
    }
    return d
  }
  const back = face(dx, dy)
  const walk = `M ${n(x0)} ${n(top)} H ${n(x1)} L ${n(x1 + dx)} ${n(top + dy)} H ${n(x0 + dx)} Z`
  let louvered = ""
  if (r.chance(0.7)) {
    const a = x0 + pier + r.int(0, count - 1) * bay
    const c = a + bay - pier
    const rad = (c - a) / 2
    const spring = top + deck + rad
    louvered = shape(
      p,
      `M ${n(a)} ${n(ground)} V ${n(spring)} A ${n(rad)} ${n(rad)} 0 0 1 ${n(c)} ${n(spring)} V ${n(ground)} Z`,
      louvers(p),
    )
  }
  return {
    x1,
    top,
    svg:
      shape(p, back, "structure-shade", { "fill-rule": "evenodd" }) +
      tint(back, stipple(p), { "fill-rule": "evenodd" }) +
      shape(p, walk, "walk") +
      louvered +
      shape(p, face(0, 0), "structure", { "fill-rule": "evenodd" }),
  }
}

/** A round platform on a column, its underside solid ink, with a small observatory dome when asked. */
export function platform(
  p: Pen,
  r: Rs,
  {
    cx,
    cy,
    rx,
    ground,
    dome,
  }: { cx: number; cy: number; rx: number; ground: number; dome: boolean },
) {
  const [ry, cw] = [rx * 0.2, rx * 0.2]
  const column = `M ${n(cx - cw)} ${n(cy)} H ${n(cx + cw)} V ${n(ground)} H ${n(cx - cw)} Z`
  const shadow = `M ${n(cx + cw * 0.15)} ${n(cy)} H ${n(cx + cw)} V ${n(ground)} H ${n(cx + cw * 0.15)} Z`
  let out = shape(p, column, "platform") + tint(shadow, stipple(p))
  out +=
    shape(p, ellipse(cx, cy + ry * 0.75, rx, ry), "ink") +
    shape(p, ellipse(cx, cy, rx, ry), "platform")
  if (dome) {
    const rd = rx * r.between(0.38, 0.48)
    const base = cy - ry * 0.15
    const half = `M ${n(cx - rd)} ${n(base)} A ${n(rd)} ${n(rd)} 0 0 1 ${n(cx + rd)} ${n(base)} Z`
    const slot = `M ${n(cx - rd * 0.12)} ${n(base - rd * 0.98)} H ${n(cx + rd * 0.12)} V ${n(base - rd * 0.25)} H ${n(cx - rd * 0.12)} Z`
    const clip = p.uid("dome")
    out +=
      el("clipPath", { id: clip }, el("path", { d: half }, null)) +
      shape(p, half, "paper") +
      tint(crescent(cx, base, rd, -rd * 0.5, -rd * 0.3), stipple(p), {
        "clip-path": `url(#${clip})`,
      }) +
      shape(p, slot, "ink") +
      line(
        p,
        `M ${n(cx - rd * 0.55)} ${n(base - rd * 0.83)} Q ${n(cx - rd * 0.42)} ${n(base - rd * 0.4)} ${n(cx - rd * 0.55)} ${n(base)}`,
      )
  }
  return out
}

/** A staircase rising from (x0, y0) to (x1, y1), seen from below: a stringer over a louvered underside. */
export function stairUnder(
  p: Pen,
  r: Rs,
  { x0, y0, x1, y1 }: { x0: number; y0: number; x1: number; y1: number },
) {
  const count = r.int(10, 14)
  const run = (x1 - x0) / count
  const rise = (y0 - y1) / count
  const T = 24
  let d = `M ${n(x0)} ${n(y0 + 60)} V ${n(y0)}`
  for (let i = 0, y = y0, x = x0; i < count; i++) {
    y -= rise
    x += run
    d += ` V ${n(y)} H ${n(x)}`
  }
  const xb = x1 - ((y0 + 60 - (y1 + T)) * run) / rise
  d += ` V ${n(y1 + T)} L ${n(xb)} ${n(y0 + 60)} Z`
  const [ux, uy] = [10, 30]
  const under = `M ${n(x1)} ${n(y1 + T)} L ${n(xb)} ${n(y0 + 60)} L ${n(xb + ux)} ${n(y0 + 60 + uy)} L ${n(x1 + ux)} ${n(y1 + T + uy)} Z`
  return shape(p, under, louvers(p)) + shape(p, d, "stair")
}

/** A tall flower: a stem, two leaves with midribs, and a pompom head. */
export function flower(
  p: Pen,
  r: Rs,
  { x, head, ground }: { x: number; head: number; ground: number },
) {
  const rad = r.between(16, 24)
  let out = shape(
    p,
    `M ${n(x - 3.5)} ${n(ground)} V ${n(head)} H ${n(x + 3.5)} V ${n(ground)} Z`,
    "leaf",
  )
  for (const dir of [-1, 1]) {
    const ly = r.between(head + 70, head + 140)
    const len = r.between(42, 64)
    const leaf =
      `M ${n(x)} ${n(ly)} Q ${n(x + dir * len * 0.2)} ${n(ly - len * 0.75)} ${n(x + dir * len)} ${n(ly - len * 0.6)} ` +
      `Q ${n(x + dir * len * 0.75)} ${n(ly + len * 0.02)} ${n(x)} ${n(ly)} Z`
    out += shape(p, leaf, "leaf")
    out += line(
      p,
      `M ${n(x)} ${n(ly)} Q ${n(x + dir * len * 0.45)} ${n(ly - len * 0.45)} ${n(x + dir * len * 0.92)} ${n(ly - len * 0.58)}`,
    )
  }
  return out + ball(p, x, head - rad * 0.6, rad, "bloom")
}

// A pinwheel framed in an arch, and plants: broad leaves with pompom flowers.
import { archPath, shade } from "./buildings"
import { ball, line, pinwheel, shape, stipple, tint } from "./motifs"
import { el, n, type Pen, type Rs } from "./svg"

/** A pinwheel seen through an arch whose thick frame is drawn in `frame`. */
export function pinwheelArch(
  p: Pen,
  {
    x,
    base,
    w,
    h,
    frame,
    colour,
  }: {
    x: number
    base: number
    w: number
    h: number
    frame: string
    colour: string
  },
) {
  const t = w * 0.14
  const inner = archPath(x + t, base, w - 2 * t, h - t)
  const clip = p.uid("pw")
  const rad = Math.hypot(w / 2, h) * 1.05
  return (
    el("clipPath", { id: clip }, el("path", { d: inner }, null)) +
    el(
      "g",
      { "clip-path": `url(#${clip})` },
      pinwheel(p, x + w / 2, base - h * 0.45, rad, colour, {
        count: 16,
        twist: 0.9,
        ring: false,
      }),
    ) +
    shape(p, `${archPath(x, base, w, h)} ${inner}`, frame, {
      "fill-rule": "evenodd",
    })
  )
}

/** Broad leaves fanning from a root, with pompom flowers on stems above them. */
export function plant(
  p: Pen,
  r: Rs,
  {
    x,
    ground,
    height,
    leaf = "leaf",
    bloom = "bloom",
    blooms = 1,
  }: {
    x: number
    ground: number
    height: number
    leaf?: string
    bloom?: string
    blooms?: number
  },
) {
  let out = ""
  for (let i = 0; i < blooms; i++) {
    const sx = x + r.between(-18, 18)
    const top = ground - height * r.between(0.75, 1)
    out += shape(
      p,
      `M ${n(sx - 3)} ${n(ground)} V ${n(top)} H ${n(sx + 3)} V ${n(ground)} Z`,
      leaf,
    )
    out += ball(p, sx, top - 12, r.between(13, 20), bloom)
  }
  const leaves = r.int(4, 6)
  for (let i = 0; i < leaves; i++) {
    const a = -Math.PI / 2 + (i / (leaves - 1) - 0.5) * r.between(2.2, 2.7)
    const len = height * r.between(0.42, 0.6)
    const [ex, ey] = [x + Math.cos(a) * len, ground + Math.sin(a) * len]
    const [px, py] = [-Math.sin(a) * len * 0.28, Math.cos(a) * len * 0.28]
    const [mx, my] = [
      x + Math.cos(a) * len * 0.55,
      ground + Math.sin(a) * len * 0.55,
    ]
    const d = `M ${n(x)} ${n(ground)} Q ${n(mx + px)} ${n(my + py)} ${n(ex)} ${n(ey)} Q ${n(mx - px)} ${n(my - py)} ${n(x)} ${n(ground)} Z`
    const half = `M ${n(x)} ${n(ground)} Q ${n(mx + px)} ${n(my + py)} ${n(ex)} ${n(ey)} Z`
    out +=
      shape(p, d, i % 2 ? leaf : shade(leaf, 90)) +
      tint(half, stipple(p)) +
      line(p, `M ${n(x)} ${n(ground)} L ${n(ex)} ${n(ey)}`)
  }
  return out
}

// The shape every template shares, so scenes.ts, city.ts and formats.ts agree.
import type { Pen } from "./svg"

export interface Scene {
  w: number
  h: number
  /** How the viewBox fits its box: slice from the bottom for scenes, meet for marks. */
  fit: string
  body: (p: Pen, seed: number) => string
}

// The templates. Each draws a whole scene from a seed in its own viewBox; a page sizes the format with CSS and the
// SVG is sliced to fill its box, anchored at the bottom, so nothing is measured.
import { city } from "./city"
import { arcadeWall, band, doorway, medallion, windowScene } from "./formats"
import { defs } from "./motifs"
import { seedOf } from "./seed"

export type { Scene } from "./scene"

export const TEMPLATES = {
  city,
  window: windowScene,
  medallion,
  band,
  arcade: arcadeWall,
  doorway,
} as const
export type Template = keyof typeof TEMPLATES

/** Stipple pitch per template, in its own units, for the size it is usually shown at. */
const PITCH: Record<Template, number> = {
  city: 3.2,
  window: 3.4,
  medallion: 2.6,
  band: 3,
  arcade: 3,
  doorway: 2.6,
}

export const seedNumber = (seed: string | number) => seedOf(String(seed))
export const pitchOf = (t: Template) => PITCH[t]
